"kind": "propose",
"summary": "The container 'api' in the Deployment 'search' is throttled at its CPU limit, causing readiness probe failures. Increasing the CPU limit to 750m should alleviate the throttling.",
"hypotheses": [
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "The current revision (2) has higher CPU throttling (66%) compared to the previous revision (1) with 8%, indicating increased CPU usage from the new version.",
    "supporting": ["ev-container_cpu", "ev-revision_health"],
    "contradicting": [],
    "missing": ["ev-rollout_history", "ev-target_events"],
    "status": "supported"
  },
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The container's CPU usage (0.495) is near its limit (0.5), and throttling (64%) is causing performance issues.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the 'api' container to 750m, which should reduce throttling and improve readiness probe success rates.",
  "rationale": "The container is consistently hitting its CPU limit (0.5) with 0.495 usage, leading to 64% throttling. Increasing the limit to 750m (1.5x current) should provide enough headroom to avoid throttling and resolve the readiness probe failures observed in ev-target_events.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-revision_health"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
